const mode = "light";

function show() {
  return mode;
}

function withDark(task) {
  const mode = "dark";

  return task();
}

function local() {
  const mode = "sepia";

  return withDark(() => mode);
}

console.log(withDark(show));
console.log(local());
console.log(withDark(() => mode));
